import Foundation

/// Simplified interactive rebase (Phase 5+):
/// the todo file is generated by Bough and injected via GIT_SEQUENCE_EDITOR,
/// so no editor is ever spawned. Supported steps: pick / drop / reword
/// (reorder by arranging the lines; reword messages are injected through a
/// GIT_EDITOR wrapper that hands git the prepared message per invocation).
extension GitRepository {

    /// One plan entry for the todo file.
    struct RebaseStep: Equatable, Sendable {
        let sha: String
        let subject: String
        var dropped: Bool
        /// Non-nil marks this step as `reword` with the new message.
        var newMessage: String?

        var todoLine: String {
            if newMessage != nil { return "reword \(sha) \(subject)" }
            return "\(dropped ? "drop" : "pick") \(sha) \(subject)"
        }
    }

    /// Load the commit range `base..HEAD` (oldest first) as the editable plan.
    func rebasePlan(base: String) async throws -> [RebaseStep] {
        let result = try await runOrThrow([
            "log", "--topo-order", "--reverse",
            "--pretty=format:%H%x1f%s%x1e", "\(base)..HEAD",
        ], serial: false)
        return result.stdoutText
            .split(separator: "\u{1e}", omittingEmptySubsequences: true)
            .compactMap { raw in
                let record = String(raw).trimmingCharacters(in: .whitespacesAndNewlines)
                let fields = record.split(separator: "\u{1f}", omittingEmptySubsequences: false)
                guard fields.count == 2 else { return nil }
                return RebaseStep(sha: String(fields[0]), subject: String(fields[1]),
                                  dropped: false, newMessage: nil)
            }
    }

    /// Execute the plan. Reword steps get their messages from a queue consumed
    /// in todo order by a generated GIT_EDITOR script (reword opens the commit
    /// editor per step; our script just copies the next prepared message).
    func rebaseInteractive(base: String, steps: [RebaseStep]) async throws {
        let todo = steps.map(\.todoLine).joined(separator: "\n") + "\n"
        let workDir = FileManager.default.temporaryDirectory
            .appendingPathComponent("bough-rebase-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: workDir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: workDir) }

        let todoFile = workDir.appendingPathComponent("todo")
        try todo.write(to: todoFile, atomically: true, encoding: .utf8)

        // Message queue for reword steps, numbered in todo order.
        let rewordSteps = steps.filter { $0.newMessage != nil }
        var environment: [String: String] = [:]
        if !rewordSteps.isEmpty {
            let queueDir = workDir.appendingPathComponent("messages", isDirectory: true)
            try FileManager.default.createDirectory(at: queueDir, withIntermediateDirectories: true)
            for (index, step) in rewordSteps.enumerated() {
                let name = String(format: "msg.%03d", index + 1)
                let body = (step.newMessage ?? "").trimmingCharacters(in: .whitespacesAndNewlines) + "\n"
                try body.write(to: queueDir.appendingPathComponent(name),
                               atomically: true, encoding: .utf8)
            }
            try "1".write(to: queueDir.appendingPathComponent("count"), atomically: true, encoding: .utf8)

            let editorScript = workDir.appendingPathComponent("message-editor.sh")
            let script = """
            #!/bin/bash
            QUEUE='\(queueDir.path)'
            N=$(cat "$QUEUE/count")
            cp "$QUEUE/msg.$(printf '%03d' "$N")" "$1"
            echo $((N+1)) > "$QUEUE/count"
            """
            try script.write(to: editorScript, atomically: true, encoding: .utf8)
            try FileManager.default.setAttributes([.posixPermissions: 0o755],
                                                  ofItemAtPath: editorScript.path)
            environment["GIT_EDITOR"] = editorScript.path
        }

        // Sequence editor invocation is "<command> <todo-file>"; cp overwrites the todo.
        environment["GIT_SEQUENCE_EDITOR"] = "cp '\(todoFile.path)'"
        try await runOrThrow(["rebase", "-i", base],
                             timeout: 600,
                             extraEnvironment: environment)
    }
}
